-- DEVELOPMENT SEED ONLY. Every generated tool is draft, source_type=demo-seed and confidence_score=0.
on conflict(slug) do nothing;
select 'Demo AI Tool '||lpad(i::text,3,'0'),'demo-ai-tool-'||i,'Development seed record. Replace with verified source data before publishing.','Development seed record; not published.', 'https://example.com/demo-ai-tool-'||i,'seed://demo-ai-tool-'||i,
 (select id from public.categories order by slug offset ((i-1)%15) limit 1),(select id from public.companies order by slug offset ((i-1)%20) limit 1),'freemium','USD',false,false,'draft',null,null,'demo-seed',0,array['development seed'],array['web'] from generate_series(1,100)i on conflict(slug) do nothing;
